import tempfile,subprocess,os
js="
'use strict';
const local='http://127.0.0.1:17448',get=async url=>{let r=await fetch(url,{signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error('http'+r.status);return r.json()};
const key=u=>{try{let x=new URL(u);return /(^|\.)chatgpt\.com$/.test(x.hostname)?x.pathname.replace(/\/$/,''):''}catch{return ''}};
function rpc(url,method,params={},max=2300) {return new Promise(resolve=>{
 let ws,done=false;const st=performance.now(),timer=setTimeout(()=>end({ok:false,reason:'timeout'}),max);
 function end(z){if(done)return;done=true;clearTimeout(timer);try{ws?.close()}catch{}resolve({ok:z.ok,reason:z.reason,elapsedMs:Math.round(performance.now()-st)})}
 try{ws=new WebSocket(url);ws.addEventListener('open',()=>ws.send(JSON.stringify({id:17,method,params})));ws.addEventListener('message',e=>{try{let a=JSON.parse(e.data);if(a.id===17)end({ok:!a.error,reason:a.error?String(a.error.message).slice(0,80):'ack'})}catch{end({ok:false,reason:'parse'})}});ws.addEventListener('error',()=>end({ok:false,reason:'socket'}))}catch{end({ok:false,reason:'construct'})}
 })}
async function main(){
 const [state,cfg,ch]=await Promise.all([get(local+'/api/operator-lifecycle'),get(local+'/api/supervisor-watchdog?detect=0'),get(local+'/api/supervisor-watchdog/managed-chats?inspect=0')]);
 if(state.queuePaused!==true||cfg.config?.mode!=='off'||cfg.config?.allowAutonomousSend!==false)throw Error('autonomy_not_frozen');
 const names=['Media','Creator','Growth','Native MCP'];
 const rows=ch.chats||[];let tabs=await get('http://127.0.0.1:17410/json/list');
 const find=(name)=>{let row=rows.find(x=>x.name===name);if(!row)throw Error('unmapped_'+name);let same=tabs.filter(t=>t.webSocketDebuggerUrl&&key(t.url)===key(row.url)&&key(row.url));if(same.length!==1)throw Error('not_unique_'+name);return same[0]};
 const answer={at:new Date().toISOString(),actions:[],postProbe:[],automaticSending:false};
 for(const name of names){
  const target=find(name),u=target.webSocketDebuggerUrl;
  const before=await rpc(u,'Runtime.evaluate',{expression:'2+2',returnByValue:true,awaitPromise:false},850);
  const focus=await rpc(u,'Page.bringToFront',{},3600);
  await new Promise(r=>setTimeout(r,350));
  const after=await rpc(u,'Runtime.evaluate',{expression:'2+2',returnByValue:true,awaitPromise:false},2200);
  answer.actions.push({name,before,focus,after});
 }
 const checknames=['Bridge',...names,'QA'];
 for(const name of checknames){let u=find(name).webSocketDebuggerUrl;const state=await rpc(u,'Runtime.evaluate',{expression:'2+2',returnByValue:true,awaitPromise:false},1200);answer.postProbe.push({name,...state})}
 const qa=find('QA');
 answer.returnToQa=await rpc(qa.webSocketDebuggerUrl,'Page.bringToFront',{},3300);
 const stateAfter=await get(local+'/api/operator-lifecycle');
 answer.queuePausedAfter=stateAfter.queuePaused;
 const afterList=await get('http://127.0.0.1:17410/json/list');
 answer.originalExactTabsPresent=checknames.every(name=>{const old=find(name);return afterList.some(x=>x.id===old.id && key(x.url)===key(old.url))});
 console.log(JSON.stringify(answer));
}
main().catch(e=>{console.log(JSON.stringify({error:String(e.message).slice(0,150)}));process.exitCode=1});
"
